import React, { useEffect, useState } from "react";
import { motion } from "framer-motion";

const WorkerSplash = ({ onComplete }) => {
  const [isExiting, setIsExiting] = useState(false);

  useEffect(() => {
    const timer = setTimeout(() => setIsExiting(true), 3200);
    const finish = setTimeout(onComplete, 4400);
    return () => { 
      clearTimeout(timer); 
      clearTimeout(finish); 
    };
  }, [onComplete]);

  // Apple-style "Smooth-In" Bezier Curve
  const appleEase = [0.16, 1, 0.3, 1];

  return (
    <div className="h-screen w-full bg-[#FDFAD8] flex items-center justify-center relative overflow-hidden">

      {/* 1. THE LIQUID GRADIENT (Subtle Depth) */}
      <motion.div 
        initial={{ scale: 0.8, opacity: 0 }}
        animate={{ scale: 1.8, opacity: 0.15 }}
        transition={{ duration: 4, ease: "easeOut" }}
        className="absolute w-[600px] h-[600px] bg-[#CAD23C] rounded-full blur-[140px]"
      />

      {/* 2. THE MAIN UNIT */}
      <div className={`${isExiting ? "animate-apple-exit" : ""}`}>
        <div className="flex flex-col items-center">

          <div className="flex items-baseline px-4">
            {/* First T */}
            <motion.h1 
              initial={{ y: 250, opacity: 0 }}
              animate={{ y: 0, opacity: 1 }}
              transition={{ duration: 1.4, ease: appleEase }}
              className="text-[10rem] md:text-[14rem] font-[1000] text-[#47510B] tracking-tighter italic select-none"
            >
              T
            </motion.h1>

            {/* The 2 - "Squircle" high-end design */}
            <motion.div 
              initial={{ scale: 0, rotate: -45 }}
              animate={{ scale: 1, rotate: 12 }}
              transition={{ duration: 1.2, delay: 0.6, ease: appleEase }}
              className="mx-4 mb-8"
            >
              <div className="bg-[#FF5B03] w-20 h-20 md:w-28 md:h-28 rounded-[2.5rem] flex items-center justify-center shadow-[0_20px_50px_rgba(255,91,3,0.3)] animate-soft-glow">
                <span className="text-white text-6xl md:text-7xl font-black italic">2</span>
              </div>
            </motion.div>

            {/* Second T */}
            <motion.h1 
              initial={{ y: 250, opacity: 0 }}
              animate={{ y: 0, opacity: 1 }}
              transition={{ duration: 1.4, delay: 0.2, ease: appleEase }}
              className="text-[10rem] md:text-[14rem] font-[1000] text-[#47510B] tracking-tighter italic select-none"
            >
              T
            </motion.h1>
          </div>

          {/* THE SUBTEXT: Smooth tracking expansion */}
          <motion.div 
            initial={{ opacity: 0, letterSpacing: "0.2em" }}
            animate={{ opacity: 1, letterSpacing: "1.2em" }}
            transition={{ duration: 2.5, delay: 1.2 }}
            className="mt-[-30px] text-[#47510B] font-black text-lg uppercase pl-[1.2em] opacity-80"
          >
            Worker
          </motion.div>
        </div>
      </div>

      {/* 3. MINIMALIST LOADER (Apple Thinness) */}
      <div className="absolute bottom-24 w-40 h-[1.5px] bg-[#47510B]/5 rounded-full overflow-hidden">
        <motion.div 
          initial={{ x: "-100%" }}
          animate={{ x: "100%" }}
          transition={{ duration: 3.5, ease: "easeInOut", repeat: Infinity }}
          className="h-full bg-[#FF5B03] w-1/2"
        />
      </div>

      {/* 4. PERIMETER BRANDING */}
      <div className="absolute bottom-10 w-full px-16 flex justify-between text-[11px] font-black text-[#47510B]/20 uppercase tracking-[0.3em]">
        <span>Network_Active</span>
        <span>Build_2026.04</span>
      </div>
    </div>
  );
};

export default WorkerSplash;
